-- Bot Cobra Fase 3: CollectionAttempt (motor de régua — só agenda, não envia).
CREATE TABLE `collection_attempts` (`id` BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, `public_id` CHAR(36) NOT NULL, `tenant_id` BIGINT UNSIGNED NOT NULL, `debt_id` BIGINT UNSIGNED NOT NULL, `cycle_number` SMALLINT UNSIGNED NOT NULL, `attempt_number` SMALLINT UNSIGNED NOT NULL, `attempt_type` ENUM('INITIAL_COLLECTION', 'SAME_DAY_FOLLOWUP', 'NEXT_DAY_FOLLOWUP', 'CYCLE_RESTART', 'PROMISE_DUE', 'PROMISE_OVERDUE', 'PIX_PENDING_REMINDER', 'PARTIAL_PAYMENT_FOLLOWUP') NOT NULL, `scheduled_at` DATETIME(3) NOT NULL, `status` ENUM('SCHEDULED', 'PROCESSING', 'SENT', 'SKIPPED', 'FAILED', 'RESPONDED', 'CANCELED') NOT NULL DEFAULT 'SCHEDULED', `template_key` VARCHAR(80) NOT NULL, `notification_log_id` BIGINT UNSIGNED NULL, `sent_at` DATETIME(3) NULL, `responded_at` DATETIME(3) NULL, `skipped_at` DATETIME(3) NULL, `skip_reason` VARCHAR(500) NULL, `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3), PRIMARY KEY (`id`), UNIQUE INDEX `collection_attempts_public_id_key` (`public_id`), UNIQUE INDEX `udca_debt_cycle_attempt` (`debt_id`, `cycle_number`, `attempt_number`), INDEX `collection_attempts_tenant_id_status_scheduled_at_idx` (`tenant_id`, `status`, `scheduled_at`), CONSTRAINT `collection_attempts_tenant_id_fkey` FOREIGN KEY (`tenant_id`) REFERENCES `tenants`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `collection_attempts_debt_id_fkey` FOREIGN KEY (`debt_id`) REFERENCES `debts`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE, CONSTRAINT `collection_attempts_notification_log_id_fkey` FOREIGN KEY (`notification_log_id`) REFERENCES `notification_logs`(`id`) ON DELETE RESTRICT ON UPDATE CASCADE) DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
